import { readdirSync, readFileSync } from 'node:fs'

import { expect, it } from 'vitest'

// Pre-client phase: one canonical fresh baseline generated by scripts/rebuild-baseline.mjs.
it('keeps a single generated fresh baseline aligned with the journal', () => {
  const journal = JSON.parse(
    readFileSync(new URL('../db/migrations/meta/_journal.json', import.meta.url), 'utf8'),
  ) as { entries: { idx: number; version: string; tag: string; breakpoints: boolean }[] }
  const migrationDirectory = new URL('../db/migrations/', import.meta.url)
  const files = readdirSync(migrationDirectory)
    .filter((file) => file.endsWith('.sql'))
    .sort()
  expect(files).toEqual(['0000_initial_schema.sql'])
  expect(journal.entries).toHaveLength(1)
  expect(journal.entries[0]).toMatchObject({
    idx: 0,
    version: '7',
    tag: '0000_initial_schema',
    breakpoints: true,
  })
  expect(readdirSync(new URL('meta/', migrationDirectory)).sort()).toEqual([
    '0000_snapshot.json',
    '_journal.json',
  ])
  const baseline = readFileSync(new URL('0000_initial_schema.sql', migrationDirectory), 'utf8')
  expect(baseline).not.toMatch(
    /ALTER TABLE[^;]+(?:ADD COLUMN|DROP COLUMN|ALTER COLUMN|DROP CONSTRAINT)/i,
  )
  expect(baseline).not.toContain('legacy_company_binding')
  expect(baseline).not.toMatch(/CREATE OR REPLACE FUNCTION/i)
  expect(baseline).not.toMatch(/^SELECT subscription_periods_reconcile\(\)/im)
  // Only the reference catalog publication updates rows; no repair or upgrade backfills.
  expect(baseline.match(/^UPDATE\s.*$/gim)).toEqual([
    "UPDATE plan_versions SET status='published',published_at=now(),published_by='migration:subscription-catalog-v1';",
  ])
  for (const fn of [
    'subscription_catalog_snapshot',
    'guard_subscription_override',
    'guard_subscription_period',
    'subscription_periods_shift',
    'subscription_periods_reconcile',
  ])
    expect(baseline, fn).toContain(`CREATE FUNCTION ${fn}(`)
  // Single-clock suspension close and paid-grace freeze are part of the baseline shift function.
  expect(baseline).toContain('SET ended_at=p_since+delta')
  expect(baseline).toContain('(ends_at>p_since OR id=grace_period)')
})
